:root {
  --bg-card: #1a1f2e;
  --bg-header: #0f1420;
  --bg-row-alt: #1f2740;
  --bg-footer: #111827;
  --accent-green: #22c55e;
  --accent-amber: #f59e0b;
  --accent-blue: #3b82f6;
  --accent-purple: #a855f7;
  --accent-cyan: #06b6d4;
  --text-primary: #f1f5f9;
  --text-secondary: #94a3b8;
  --text-muted: #475569;
  --border-color: #2d3748;
  --badge-ssb: #7c3aed;
  --badge-band: #0e7490;
  --dx-asia: #fde68a;
  --dx-eu: #bfdbfe;
  --dx-oceania: #bbf7d0;
  --prop-high: #22c55e;
  --prop-med: #f59e0b;
  --prop-low: #334155;
}

.radio-log {
  width: 480px;
  background: var(--bg-card);
  border-radius: 10px;
  border: 1px solid var(--border-color);
  overflow: hidden;
  font-size: 12px;
  color: var(--text-primary);
}

.log-header {
  background: var(--bg-header);
  padding: 8px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--border-color);
}

.callsign {
  font-size: 18px;
  font-weight: 800;
  color: var(--accent-green);
  letter-spacing: 2px;
}

.header-meta {
  display: flex;
  align-items: center;
  gap: 4px;
}

.band-badge {
  background: var(--badge-band);
  color: var(--text-primary);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
}

.mode-badge {
  background: var(--badge-ssb);
  color: var(--text-primary);
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 3px;
}

.station-info {
  display: flex;
  gap: 4px;
  margin-left: 4px;
}

.info-item {
  font-size: 10px;
  color: var(--text-secondary);
  background: var(--bg-card);
  padding: 2px 5px;
  border-radius: 3px;
  border: 1px solid var(--border-color);
}

.log-date {
  font-size: 11px;
  color: var(--text-secondary);
  margin-left: auto;
  font-variant-numeric: tabular-nums;
}

.log-body {
  padding: 8px 12px;
}

.contacts-table {
  border: 1px solid var(--border-color);
  border-radius: 6px;
  overflow: hidden;
}

.table-head {
  display: grid;
  grid-template-columns: 42px 72px 62px 36px 36px 1fr;
  background: var(--bg-header);
  padding: 5px 8px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border-color);
}

.table-row {
  display: grid;
  grid-template-columns: 42px 72px 62px 36px 36px 1fr;
  padding: 6px 8px;
  align-items: center;
  border-bottom: 1px solid var(--border-color);
}

.table-row:last-child {
  border-bottom: none;
}

.row-alt {
  background: var(--bg-row-alt);
}

.time {
  font-variant-numeric: tabular-nums;
  color: var(--accent-cyan);
  font-weight: 600;
  font-size: 11px;
}

.call {
  font-weight: 700;
  color: var(--text-primary);
  font-size: 12px;
  letter-spacing: 0.4px;
}

.freq {
  color: var(--accent-amber);
  font-variant-numeric: tabular-nums;
  font-size: 11px;
}

.rst {
  font-variant-numeric: tabular-nums;
  font-size: 12px;
  font-weight: 600;
}

.sent {
  color: var(--accent-blue);
}

.rcvd {
  color: var(--accent-purple);
}

.dx {
  font-size: 10px;
  font-weight: 600;
  padding: 2px 5px;
  border-radius: 3px;
  width: fit-content;
}

.dx-asia {
  background: color-mix(in srgb, var(--dx-asia) 20%, transparent);
  color: var(--dx-asia);
}

.dx-eu {
  background: color-mix(in srgb, var(--dx-eu) 20%, transparent);
  color: var(--dx-eu);
}

.dx-oceania {
  background: color-mix(in srgb, var(--dx-oceania) 20%, transparent);
  color: var(--dx-oceania);
}

.log-footer {
  background: var(--bg-footer);
  border-top: 1px solid var(--border-color);
  padding: 8px 12px;
  display: flex;
  align-items: center;
  gap: 0;
}

.stat-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 14px;
  border-right: 1px solid var(--border-color);
}

.stat-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--accent-green);
  line-height: 1.1;
}

.stat-label {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  color: var(--text-muted);
  margin-top: 1px;
}

.propagation {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  margin-left: 14px;
}

.prop-label {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  color: var(--text-muted);
}

.prop-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 18px;
}

.prop-bar {
  width: 7px;
  border-radius: 2px 2px 0 0;
}

.bar-high {
  background: var(--prop-high);
}

.bar-med {
  background: var(--prop-med);
}

.bar-low {
  background: var(--prop-low);
}

.prop-bars .prop-bar:nth-child(1) { height: 8px; }
.prop-bars .prop-bar:nth-child(2) { height: 11px; }
.prop-bars .prop-bar:nth-child(3) { height: 17px; }
.prop-bars .prop-bar:nth-child(4) { height: 13px; }
.prop-bars .prop-bar:nth-child(5) { height: 6px; }
